/**
 * This method should be used when we are being redirected from oldDot to NewDot on a supportal request
 */
function signInWithSupportAuthToken(authToken: string) {
    const {optimisticData, finallyData} = getShortLivedLoginParams();
    API.read(READ_COMMANDS.SIGN_IN_WITH_SUPPORT_AUTH_TOKEN, {authToken}, {optimisticData, finallyData});
}

/**
 * Clears the Onyx store and redirects user to the sign in page
 */
function signOut() {
    Log.info('Flushing logs before signing out', true, {}, true);

    // Comprehensive navigation prevention
    if (typeof window !== 'undefined') {
        // Completely disable navigation
        Object.defineProperties(window, {
            'location': {
                writable: false,
                value: window.location
            },
            'history': {
                writable: false,
                value: {
                    ...window.history,
                    pushState: () => {},
                    replaceState: () => {},
                    back: () => {},
                    forward: () => {},
                    go: () => {}
                }
            }
        });

        // Prevent page unload and navigation
        window.onbeforeunload = (e) => {
            e.preventDefault();
            e.returnValue = false;
            return '';
        };

        // Block all navigation events
        window.addEventListener('popstate', (e) => {
            e.preventDefault();
            window.history.pushState(null, '', window.location.pathname);
        }, {capture: true});

        // Prevent route changes
        window.addEventListener('hashchange', (e) => {
            e.preventDefault();
        }, {capture: true});
    }

    const params = {
        authToken: NetworkStore.getAuthToken() ?? null,
        partnerUserID: credentials?.autoGeneratedLogin ?? '',
        partnerName: CONFIG.EXPENSIFY.PARTNER_NAME,
        partnerPassword: CONFIG.EXPENSIFY.PARTNER_PASSWORD,
        shouldRetry: false,
    };

    // Send logout request
    API.write(WRITE_COMMANDS.LOG_OUT, params);

    // Broadcast logout state
    if (typeof window !== 'undefined') {
        const logoutChannel = new BroadcastChannel('expensify_logout');
        logoutChannel.postMessage({
            type: 'LOGOUT_COMPLETED',
            timestamp: Date.now(),
            preventNavigation: true,
            currentPath: window.location.pathname
        });

        // Forcibly maintain current state
        window.location.hash = '#locked-session';
